// data.catalog_gc — catalog GC / payload dedup / entity pagination against
// the frozen Python oracles (fixtures/catalog_gc/*, generated by
// tools/oracle/generate_catalog_gc_fixtures.py from the real
// DataCatalogService + catalog.gc + catalog.dedup + paged-query stack).
//
// Every scenario tree ships with its catalog.sqlite and payloads; the test
// copies it to a temp root, loads the same store through CatalogRepository
// and must reproduce every frozen value: GC classification sets, sweep
// outcomes (removed + remaining file set), blob-store metrics and
// reachability sweeps, place_managed_file results and error texts, and the
// full paged-query row matrix.
#include "pwb_test.hpp"
#include "compare_json.hpp"

#include "pwb/catalog/dedup.hpp"
#include "pwb/catalog/entity_view.hpp"
#include "pwb/catalog/gc.hpp"
#include "pwb/catalog/repository.hpp"
#include "pwb/domain/json.hpp"
#include "pwb/domain/sha256.hpp"
#include "pwb/project/paths.hpp"

#include <algorithm>
#include <filesystem>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

namespace {

namespace fs = std::filesystem;
using pwb::catalog::CatalogDocument;
using pwb::catalog::CatalogRepository;
using pwb::domain::Json;

fs::path scenario_dir(const char* name) {
    return fs::path(PWB_DATA_FIXTURE_DIR) / "catalog_gc" / name;
}

Json load_json(const fs::path& file) {
    std::ifstream stream(file, std::ios::binary);
    std::ostringstream buffer;
    buffer << stream.rdbuf();
    return Json::parse(buffer.str(), nullptr, false);
}

// Git tracks files, not directories: empty fixture directories (the GC
// empty_dir subjects) do not survive a fresh clone. The frozen oracle lists
// them; recreate before any plan runs (decisions D16).
void materialize_empty_dirs(const fs::path& root, const char* name) {
    const Json oracle = load_json(scenario_dir(name) / "oracle.json");
    if (!oracle.contains("fabricated_empty_dirs")) return;
    for (const auto& rel : oracle["fabricated_empty_dirs"]) {
        std::error_code ec;
        fs::create_directories(root / pwb::project::path_from_u8(
                                       rel.get<std::string>()), ec);
    }
}

struct Scratch {
    fs::path root;
    fs::path project;

    static Scratch from_scenario(const char* name, const char* variant) {
        Scratch scratch;
        scratch.root = fs::temp_directory_path()
            / ("pwb_catalog_gc_" + std::string(name) + "_"
               + std::string(variant));
        std::error_code ec;
        fs::remove_all(scratch.root, ec);
        fs::create_directories(scratch.root, ec);
        fs::copy(scenario_dir(name) / "tree", scratch.root,
                 fs::copy_options::recursive
                     | fs::copy_options::overwrite_existing,
                 ec);
        scratch.project = scratch.root / "demo.paleo.json";
        materialize_empty_dirs(scratch.root, name);
        return scratch;
    }

    static Scratch from_scenario(const char* name) {
        return from_scenario(name, "main");
    }

    ~Scratch() {
        std::error_code ec;
        fs::remove_all(root, ec);
    }
};

CatalogDocument load_document(const Scratch& scratch) {
    CatalogRepository repository(
        pwb::project::catalog_sqlite_for(scratch.project));
    auto document = repository.open_read_only();
    if (!document.is_ok()) {
        std::cout << "  FAIL [fixture] catalog unreadable: "
                  << document.error().message << "\n";
        return CatalogDocument{};
    }
    return std::move(document.value());
}

std::vector<std::string> tree_files(const fs::path& root) {
    // Same rule as the generator's _tree_files: store bookkeeping is
    // excluded — artifacts/metadata/ (canonical sqlite, WAL sidecars,
    // manifest checkpoints) and the telemetry log (artifacts/catalog/) are
    // not GC subjects, and the C++ replay implements no manifest/telemetry
    // writer.
    std::vector<std::string> files;
    const fs::path bookkeeping[] = {
        root / "demo.artifacts" / "metadata",
        root / "demo.artifacts" / "catalog",
    };
    auto excluded = [&](const fs::path& path) {
        for (const fs::path& base : bookkeeping) {
            std::error_code rel_ec;
            const fs::path rel = fs::relative(path, base, rel_ec);
            if (!rel_ec && !rel.empty()
                && (rel.begin() == rel.end() || (*rel.begin()) != "..")) {
                return true;
            }
        }
        return false;
    };
    for (const auto& entry : fs::recursive_directory_iterator(root)) {
        std::error_code ec;
        if (!entry.is_regular_file(ec) || ec) continue;
        if (excluded(entry.path())) continue;
        files.push_back(
            pwb::project::path_to_u8(fs::relative(entry.path(), root)));
    }
    std::sort(files.begin(), files.end());
    return files;
}

std::string replace_all(std::string text, const std::string& needle,
                        const std::string& replacement) {
    std::size_t at = text.find(needle);
    while (at != std::string::npos) {
        text.replace(at, needle.size(), replacement);
        at = text.find(needle, at + replacement.size());
    }
    return text;
}

// Reports compare as (kind, rel_path, size) sets — Python rglob order is not
// part of the contract.
std::vector<std::string> item_keys(const Json& items) {
    std::vector<std::string> keys;
    for (const auto& item : items) {
        std::ostringstream key;
        key << item["kind"].get<std::string>() << "|"
            << item["rel"].get<std::string>() << "|"
            << item["size"].get<std::int64_t>();
        keys.push_back(key.str());
    }
    std::sort(keys.begin(), keys.end());
    return keys;
}

std::vector<std::string> report_keys(const pwb::catalog::GcReport& report) {
    std::vector<std::string> keys;
    for (const auto& item : report.items) {
        keys.push_back(item.kind + "|" + item.rel_path + "|"
                       + std::to_string(item.size));
    }
    std::sort(keys.begin(), keys.end());
    return keys;
}

void check_items_match(const char* what, const Json& expected,
                       const pwb::catalog::GcReport& actual) {
    const std::vector<std::string> want = item_keys(expected);
    const std::vector<std::string> got = report_keys(actual);
    if (want != got) {
        std::cout << "  FAIL [" << what << "] classification set mismatch\n";
        for (const std::string& key : want) {
            if (std::find(got.begin(), got.end(), key) == got.end()) {
                std::cout << "    missing: " << key << "\n";
            }
        }
        for (const std::string& key : got) {
            if (std::find(want.begin(), want.end(), key) == want.end()) {
                std::cout << "    extra:   " << key << "\n";
            }
        }
        ::pwb_test::check(false, "item sets equal", __FILE__, __LINE__);
        return;
    }
    PWB_CHECK(true);
}

void check_removed_match(const char* what, const Json& expected,
                         const pwb::catalog::GcReport& actual) {
    std::vector<std::string> want;
    for (const auto& item : expected) {
        want.push_back(item["kind"].get<std::string>() + "|"
                       + item["rel"].get<std::string>());
    }
    std::sort(want.begin(), want.end());
    std::vector<std::string> got;
    for (const auto& item : actual.items) {
        got.push_back(item.kind + "|" + item.rel_path);
    }
    std::sort(got.begin(), got.end());
    PWB_CHECK(want == got);
}

void check_string_vectors(const char* what,
                          const std::vector<std::string>& actual,
                          const Json& expected) {
    std::vector<std::string> want;
    for (const auto& value : expected) {
        want.push_back(value.get<std::string>());
    }
    std::sort(want.begin(), want.end());
    std::vector<std::string> got = actual;
    std::sort(got.begin(), got.end());
    if (want != got) {
        std::cout << "  FAIL [" << what << "] vector mismatch (want "
                  << want.size() << ", got " << got.size() << ")\n";
        PWB_CHECK(false);
        return;
    }
    PWB_CHECK(true);
}

// ------------------------------------------------------------------ paging

pwb::catalog::EntityPageQuery query_from_json(const Json& spec) {
    pwb::catalog::EntityPageQuery query;
    if (spec.contains("text")) query.text = spec["text"].get<std::string>();
    if (spec.contains("stage")) {
        query.stage = spec["stage"].get<std::string>();
    }
    if (spec.contains("tags")) {
        for (const auto& tag : spec["tags"]) {
            query.tags.push_back(tag.get<std::string>());
        }
    }
    if (spec.contains("tag_op")) {
        query.tag_op = spec["tag_op"].get<std::string>();
    }
    if (spec.contains("type")) {
        query.type = spec["type"].get<std::string>();
    }
    if (spec.contains("asset_id")) {
        query.asset_id = spec["asset_id"].get<std::string>();
    }
    if (spec.contains("asset_ids")) {
        for (const auto& id : spec["asset_ids"]) {
            query.asset_ids.push_back(id.get<std::string>());
        }
    }
    if (spec.contains("include_trashed")) {
        query.include_trashed = spec["include_trashed"].get<bool>();
    }
    if (spec.contains("trashed_only")) {
        query.trashed_only = spec["trashed_only"].get<bool>();
    }
    if (spec.contains("order_by")) {
        query.order_by = spec["order_by"].get<std::string>();
    }
    if (spec.contains("limit")) {
        query.limit = spec["limit"].get<std::int64_t>();
    }
    if (spec.contains("offset")) {
        query.offset = spec["offset"].get<std::int64_t>();
    }
    if (spec.contains("after")) {
        query.after = {spec["after"][0].get<std::string>(),
                       spec["after"][1].get<std::string>()};
    }
    return query;
}

// The metadata row field is a JSON TEXT column: Python freezes it parsed
// (decisions D7); the C++ row string must parse to the same object.
bool metadata_matches(const Json& actual_row, const Json& expected_row,
                      std::string* diff) {
    const Json parsed = Json::parse(
        actual_row["metadata"].get<std::string>(), nullptr, false);
    if (parsed.is_discarded()) {
        *diff = "metadata column is not valid JSON";
        return false;
    }
    const auto result = pwb_test::json_compare(parsed, expected_row["metadata"]);
    if (result.has_value()) {
        *diff = *result;
        return false;
    }
    return true;
}

void check_row_matches(const Json& expected, const Json& actual) {
    for (auto it = expected.begin(); it != expected.end(); ++it) {
        const std::string& key = it.key();
        if (!actual.contains(key)) {
            std::cout << "  FAIL [row] missing key " << key << "\n";
            PWB_CHECK(false);
            continue;
        }
        if (key == "metadata") {
            std::string diff;
            if (!metadata_matches(actual, expected, &diff)) {
                std::cout << "  FAIL [row.metadata] " << diff << "\n";
                PWB_CHECK(false);
            }
            continue;
        }
        const Json& want = it.value();
        const Json& got = actual[key];
        if (want.is_number_integer() && got.is_number_integer()) {
            PWB_CHECK(want.get<std::int64_t>() == got.get<std::int64_t>());
        } else if (want.is_null()) {
            PWB_CHECK(got.is_null());
        } else {
            PWB_CHECK(want == got);
        }
    }
    PWB_CHECK(actual.size() == expected.size());
}

}  // namespace

PWB_TEST(gc_plan_classifies_every_orphan_class) {
    Scratch scratch = Scratch::from_scenario("gc_orphans");
    const CatalogDocument document = load_document(scratch);
    const pwb::catalog::GcContext context{scratch.project, &document};
    const Json oracle = load_json(scenario_dir("gc_orphans") / "oracle.json");

    const pwb::catalog::GcReport plan =
        pwb::catalog::plan_gc(context, /*explicit_plan=*/true);
    check_items_match("plan_gc(explicit)", oracle["plan_explicit"], plan);
    // GcReport aggregate accessors are part of the Python contract surface.
    PWB_CHECK(plan.total_bytes()
              == plan.items.empty() ? 0 : [&] {
                     std::int64_t sum = 0;
                     for (const auto& item : oracle["plan_explicit"]) {
                         sum += item["size"].get<std::int64_t>();
                     }
                     return sum;
                 }());
    std::int64_t temp_bytes = 0;
    for (const auto& item : oracle["plan_explicit"]) {
        if (item["kind"] == "temp_orphan") {
            temp_bytes += item["size"].get<std::int64_t>();
        }
    }
    PWB_CHECK(plan.bytes_for(pwb::catalog::kGcTempOrphan) == temp_bytes);

    // Every orphan class appears in the explicit plan.
    for (const char* kind :
         {pwb::catalog::kGcStageOrphan, pwb::catalog::kGcWorkingOrphan,
          pwb::catalog::kGcTempOrphan, pwb::catalog::kGcTrashOrphan,
          pwb::catalog::kGcBlobOrphan, pwb::catalog::kGcEmptyDir}) {
        PWB_CHECK(plan.count(kind) >= 1);
    }
    // The lease-guarded stage payload and the referenced payloads are never
    // classified.
    const std::string leased = oracle["meta"]["leased_stage_orphan"];
    PWB_CHECK(plan.count(pwb::catalog::kGcStageOrphan) >= 1);
    for (const auto& item : plan.items) {
        PWB_CHECK(item.rel_path != leased);
    }

    const pwb::catalog::GcReport auto_plan =
        pwb::catalog::plan_gc(context, /*explicit_plan=*/false);
    check_items_match("plan_gc(auto)", oracle["plan_auto"], auto_plan);
    PWB_CHECK(auto_plan.count(pwb::catalog::kGcStageOrphan) == 0);
    PWB_CHECK(auto_plan.count(pwb::catalog::kGcWorkingOrphan) == 0);
    PWB_CHECK(auto_plan.count(pwb::catalog::kGcTrashOrphan) == 0);
    PWB_CHECK(auto_plan.count(pwb::catalog::kGcBlobOrphan) == 0);

    // Planning deletes nothing.
    PWB_CHECK(fs::exists(scratch.root
                         / pwb::project::path_from_u8(
                             oracle["meta"]["referenced_temp_payload"]
                                 .get<std::string>())));
}

PWB_TEST(gc_sweep_auto_and_explicit_match_frozen_outcomes) {
    const Json oracle = load_json(scenario_dir("gc_orphans") / "oracle.json");

    // Conservative (open-time) sweep: temp + empty dirs only.
    {
        Scratch scratch = Scratch::from_scenario("gc_orphans", "auto");
        const CatalogDocument document = load_document(scratch);
        const pwb::catalog::GcContext context{scratch.project, &document};
        const pwb::catalog::GcReport dry =
            pwb::catalog::sweep_gc(context, /*dry_run=*/true,
                                   /*explicit_sweep=*/false);
        check_removed_match("sweep_auto(dry)", oracle["sweep_auto"]["removed"],
                            dry);
        PWB_CHECK(dry.count(pwb::catalog::kGcTempOrphan) >= 1);

        const pwb::catalog::GcReport removed =
            pwb::catalog::sweep_gc(context, /*dry_run=*/false,
                                   /*explicit_sweep=*/false);
        check_removed_match("sweep_auto", oracle["sweep_auto"]["removed"],
                            removed);
        check_string_vectors("sweep_auto remaining", tree_files(scratch.root),
                             oracle["sweep_auto"]["remaining_files"]);
        // Payloads untouched by the conservative sweep.
        PWB_CHECK(fs::exists(scratch.root
                             / pwb::project::path_from_u8(
                                 oracle["meta"]["referenced_temp_payload"]
                                     .get<std::string>())));
        PWB_CHECK(fs::exists(scratch.root
                             / pwb::project::path_from_u8(
                                 oracle["meta"]["live_working_rel"]
                                     .get<std::string>())));
        // Working copies are never swept, not even explicitly.
        PWB_CHECK(removed.count(pwb::catalog::kGcWorkingOrphan) == 0);
    }

    // Explicit sweep: stage/temp/trash/blob/empty go, working stays.
    {
        Scratch scratch = Scratch::from_scenario("gc_orphans", "explicit");
        const CatalogDocument document = load_document(scratch);
        const pwb::catalog::GcContext context{scratch.project, &document};
        const pwb::catalog::GcReport removed =
            pwb::catalog::sweep_gc(context, /*dry_run=*/false,
                                   /*explicit_sweep=*/true);
        check_removed_match("sweep_explicit",
                            oracle["sweep_explicit"]["removed"], removed);
        check_string_vectors("sweep_explicit remaining",
                             tree_files(scratch.root),
                             oracle["sweep_explicit"]["remaining_files"]);
        PWB_CHECK(fs::exists(scratch.root
                             / pwb::project::path_from_u8(
                                 oracle["meta"]["live_working_rel"]
                                     .get<std::string>())));
        PWB_CHECK(fs::exists(scratch.root
                             / pwb::project::path_from_u8(
                                 oracle["meta"]["leased_stage_orphan"]
                                     .get<std::string>())));
    }

    // External source files (outside artifacts/) are never touched.
    {
        Scratch scratch = Scratch::from_scenario("gc_orphans", "ext");
        const CatalogDocument document = load_document(scratch);
        const pwb::catalog::GcContext context{scratch.project, &document};
        pwb::catalog::sweep_gc(context, false, true);
        const Json before = load_json(scratch.project);  // readable = intact
        PWB_CHECK(before.is_object());
        PWB_CHECK(fs::exists(scratch.root / "incoming" / "a.bin"));
    }
}

PWB_TEST(gc_cleanup_working_copies_only_removes_unknown_versions) {
    Scratch scratch = Scratch::from_scenario("gc_orphans", "cleanup");
    const CatalogDocument document = load_document(scratch);
    const pwb::catalog::GcContext context{scratch.project, &document};
    const Json oracle = load_json(scenario_dir("gc_orphans") / "oracle.json");

    const pwb::catalog::GcReport removed =
        pwb::catalog::cleanup_working_copies(context);
    check_removed_match("cleanup_working_copies",
                        oracle["cleanup_working_copies"]["removed"], removed);
    check_string_vectors("cleanup remaining", tree_files(scratch.root),
                         oracle["cleanup_working_copies"]["remaining_files"]);
    // Live versions' working copies survive the explicit hook.
    PWB_CHECK(fs::exists(scratch.root
                         / pwb::project::path_from_u8(
                             oracle["meta"]["live_working_rel"]
                                 .get<std::string>())));
}

PWB_TEST(dedup_blob_store_matches_python_metrics_and_gc) {
    Scratch scratch = Scratch::from_scenario("dedup_flow");
    const CatalogDocument document = load_document(scratch);
    const Json oracle = load_json(scenario_dir("dedup_flow") / "oracle.json");

    // The frozen digest identities match the shipped payload bytes.
    PWB_CHECK(pwb::domain::Sha256::of_file(scratch.root / "incoming" / "one.bin")
                  .value() == oracle["digest_p"].get<std::string>());
    PWB_CHECK(pwb::domain::Sha256::of_file(scratch.root / "incoming" / "three.bin")
                  .value() == oracle["digest_q"].get<std::string>());
    PWB_CHECK(pwb::domain::Sha256::of_file(scratch.root / "incoming" / "junk.bin")
                  .value() == oracle["digest_junk"].get<std::string>());

    // blob_report_after is fully reproducible from the shipped document +
    // blob store: metrics, unreferenced and referenced digests.
    const Json report = oracle["blob_report_after"];
    const pwb::catalog::BlobMetrics report_metrics =
        pwb::catalog::blob_metrics(scratch.project, document);
    PWB_CHECK(report_metrics.blobs_on_disk
              == report["metrics"]["blobs_on_disk"].get<std::int64_t>());
    PWB_CHECK(report_metrics.bytes_deduped
              == report["metrics"]["bytes_deduped"].get<std::int64_t>());
    check_string_vectors("blob_report unreferenced",
                         pwb::catalog::plan_blob_gc(scratch.project, document),
                         report["unreferenced"]);
    check_string_vectors("blob_report referenced",
                         pwb::catalog::referenced_digests(document),
                         report["referenced"]);

    // The deduped version points at the shared blob; trash/restore never
    // moved it (three frozen path snapshots are identical).
    const std::string v2_path =
        oracle["v2_path_before"].get<std::string>();
    PWB_CHECK(oracle["v2_is_blob_backed"].get<bool>());
    PWB_CHECK(v2_path == oracle["v2_path_after_trash"].get<std::string>());
    PWB_CHECK(v2_path == oracle["v2_path_after_restore"].get<std::string>());
    PWB_CHECK(oracle["blob_of_v2_still_there"].get<bool>());
    PWB_CHECK(oracle["purge_removed"].get<std::int64_t>() == 1);

    // Version rows in the copied store equal the frozen final state.
    for (const auto& version : oracle["versions"]) {
        const auto* row = document.find_version(
            pwb::domain::VersionId(version["id"].get<std::string>()));
        PWB_CHECK(row != nullptr);
        if (row == nullptr) continue;
        PWB_CHECK(row->path == version["path"].get<std::string>());
        PWB_CHECK(row->size_bytes.has_value()
                  && *row->size_bytes
                      == version["size_bytes"].get<std::int64_t>());
        PWB_CHECK(row->sha256.has_value()
                  && *row->sha256 == version["sha256"].get<std::string>());
        PWB_CHECK(row->trashed == version["trashed"].get<bool>());
    }

    // Metrics on the post-purge document match the frozen after-snapshot.
    const pwb::catalog::BlobMetrics metrics =
        pwb::catalog::blob_metrics(scratch.project, document);
    const Json& want = oracle["metrics_after"];
    PWB_CHECK(metrics.blobs_on_disk == want["blobs_on_disk"].get<std::int64_t>());
    PWB_CHECK(metrics.bytes_on_disk == want["bytes_on_disk"].get<std::int64_t>());
    PWB_CHECK(metrics.referenced_digests
              == want["referenced_digests"].get<std::int64_t>());
    PWB_CHECK(metrics.unreferenced_blobs
              == want["unreferenced_blobs"].get<std::int64_t>());
    PWB_CHECK(metrics.bytes_deduped == want["bytes_deduped"].get<std::int64_t>());

    // Reachability plan + sweep: only the orphaned digests go; the shared
    // blob referenced by the surviving version stays.
    check_string_vectors("plan_blob_gc",
                         pwb::catalog::plan_blob_gc(scratch.project, document),
                         oracle["plan_after"]);

    // Placement is idempotent while the blob exists (junk content is still
    // on disk at this point).
    const fs::path junk = scratch.root / "incoming" / "junk.bin";
    auto placed = pwb::catalog::place_blob(scratch.project, junk);
    PWB_CHECK(placed.is_ok() && !placed.value().newly_placed);

    std::vector<std::string> removed;
    PWB_CHECK(pwb::catalog::sweep_unreferenced_blobs(scratch.project, document,
                                                     &removed).ok());
    check_string_vectors("sweep removed", removed, oracle["sweep"]["removed"]);
    for (const std::string& digest : removed) {
        PWB_CHECK(!pwb::catalog::has_blob(scratch.project, digest));
    }
    std::vector<std::string> remaining;
    for (const auto& [digest, size] :
         pwb::catalog::scan_blobs(scratch.project)) {
        (void)size;
        remaining.push_back(pwb::project::path_to_u8(
            pwb::catalog::blob_path_for(scratch.project, digest)
                .lexically_relative(scratch.root)));
    }
    check_string_vectors("remaining blobs", remaining,
                         oracle["sweep"]["remaining_blobs"]);

    // After the sweep, re-placing the swept content places it anew — and
    // marks it read-only (content-addressed, immutable by contract).
    auto re_placed = pwb::catalog::place_blob(scratch.project, junk);
    PWB_CHECK(re_placed.is_ok() && re_placed.value().newly_placed);
    std::error_code ec;
    const auto perms = fs::status(
        pwb::catalog::blob_path_for(scratch.project,
                                    re_placed.value().digest), ec)
        .permissions();
    PWB_CHECK(!ec && (perms & fs::perms::owner_write) == fs::perms::none);
}

PWB_TEST(place_managed_file_rules_and_error_texts) {
    Scratch scratch = Scratch::from_scenario("place_rules");
    const Json oracle = load_json(scenario_dir("place_rules") / "oracle.json");
    const fs::path incoming = scratch.root / "incoming";

    auto normalize = [&](const std::string& message) {
        return replace_all(message, pwb::project::path_to_u8(scratch.root),
                           "<ROOT>");
    };
    auto check_error_case = [&](const char* name,
                                pwb::domain::ErrorCode code,
                                const pwb::domain::Result<
                                    pwb::catalog::PlacedFile>& result) {
        const Json& expected = oracle["cases"][name];
        PWB_CHECK(!result.is_ok());
        if (result.is_ok()) return;
        PWB_CHECK(result.error().code == code);
        PWB_CHECK(normalize(result.error().message)
                  == expected["error"].get<std::string>());
    };

    // ok_new: plain stage copy with honest hash/size.
    {
        auto result = pwb::catalog::place_managed_file(
            incoming / "one.bin", scratch.project,
            pwb::domain::DataStage::Raw, "asset_p1", "ver_p1");
        PWB_CHECK(result.is_ok());
        if (result.is_ok()) {
            const Json& want = oracle["cases"]["ok_new"];
            PWB_CHECK(result.value().rel_path
                      == want["rel_path"].get<std::string>());
            PWB_CHECK(result.value().size_bytes
                      == want["size_bytes"].get<std::int64_t>());
            PWB_CHECK(result.value().sha256 == want["sha256"].get<std::string>());
        }
    }
    // dedup_adopt: same digest + size + content → copy-free blob reference.
    {
        auto seed = pwb::catalog::place_blob(
            scratch.project, incoming / "seed_b.bin",
            oracle["digest_b"].get<std::string>());
        // The fixture tree ships no blobs: seeding is a fresh placement.
        PWB_CHECK(seed.is_ok() && seed.value().newly_placed);
        pwb::catalog::PlaceManagedOptions options;
        options.known_sha256 = oracle["digest_b"].get<std::string>();
        auto result = pwb::catalog::place_managed_file(
            incoming / "seed_b2.bin", scratch.project,
            pwb::domain::DataStage::Derived, "asset_p2", "ver_p2", options);
        PWB_CHECK(result.is_ok());
        if (result.is_ok()) {
            const Json& want = oracle["cases"]["dedup_adopt"];
            PWB_CHECK(result.value().rel_path
                      == want["rel_path"].get<std::string>());
            PWB_CHECK(result.value().size_bytes
                      == want["size_bytes"].get<std::int64_t>());
            PWB_CHECK(result.value().sha256 == want["sha256"].get<std::string>());
            PWB_CHECK(fs::exists(incoming / "seed_b2.bin"));
        }
    }
    // dedup_move: keep_source=false consumes the working file; the payload
    // lands under the OUTPUT stage dir name ("outputs") and a blob is
    // registered from the same read.
    {
        pwb::catalog::PlaceManagedOptions options;
        options.keep_source = false;
        options.register_blob = true;
        auto result = pwb::catalog::place_managed_file(
            incoming / "move_me.bin", scratch.project,
            pwb::domain::DataStage::Output, "asset_p3", "ver_p3", options);
        PWB_CHECK(result.is_ok());
        if (result.is_ok()) {
            const Json& want = oracle["cases"]["dedup_move"];
            PWB_CHECK(result.value().rel_path
                      == want["rel_path"].get<std::string>());
            PWB_CHECK(result.value().size_bytes
                      == want["size_bytes"].get<std::int64_t>());
            PWB_CHECK(result.value().sha256 == want["sha256"].get<std::string>());
            PWB_CHECK(want["source_removed"].get<bool>());
            PWB_CHECK(want["blob_placed"].get<bool>());
            PWB_CHECK(!fs::exists(incoming / "move_me.bin"));
        }
    }
    // Honest checksum: a caller digest that does not match the bytes is
    // rejected with the exact Python text; nothing is committed.
    {
        pwb::catalog::PlaceManagedOptions options;
        options.known_sha256 = std::string(64, '0');
        check_error_case(
            "err_mismatch", pwb::domain::ErrorCode::InvalidArgument,
            pwb::catalog::place_managed_file(
                incoming / "mm.bin", scratch.project,
                pwb::domain::DataStage::Raw, "asset_pe", "ver_mismatch",
                options));
    }
    // Same SIZE as an existing blob, different content, stale digest: the
    // fast path re-proofs the content and refuses to adopt.
    {
        auto seed = pwb::catalog::place_blob(
            scratch.project, incoming / "sized.bin",
            oracle["digest_sized"].get<std::string>());
        PWB_CHECK(seed.is_ok() && seed.value().newly_placed);
        PWB_CHECK(pwb::catalog::has_blob(
            scratch.project, oracle["digest_sized"].get<std::string>()));
        pwb::catalog::PlaceManagedOptions options;
        options.known_sha256 = oracle["digest_sized"].get<std::string>();
        check_error_case(
            "err_same_size_diff_content",
            pwb::domain::ErrorCode::InvalidArgument,
            pwb::catalog::place_managed_file(
                incoming / "twin.bin", scratch.project,
                pwb::domain::DataStage::Raw, "asset_pe", "ver_same_size",
                options));
    }
    // A second placement onto the same target is refused (immutable).
    {
        auto first = pwb::catalog::place_managed_file(
            incoming / "dup.bin", scratch.project, pwb::domain::DataStage::Raw,
            "asset_p5", "ver_p5");
        PWB_CHECK(first.is_ok());
        check_error_case(
            "err_exists", pwb::domain::ErrorCode::ImmutableVersion,
            pwb::catalog::place_managed_file(
                incoming / "dup.bin", scratch.project,
                pwb::domain::DataStage::Raw, "asset_p5", "ver_p5"));
    }
    // Unsafe ids never create directories.
    {
        check_error_case(
            "err_unsafe_asset", pwb::domain::ErrorCode::UnsafeId,
            pwb::catalog::place_managed_file(
                incoming / "dup.bin", scratch.project,
                pwb::domain::DataStage::Raw, "../evil", "ver_x"));
        check_error_case(
            "err_unsafe_asset_dot", pwb::domain::ErrorCode::UnsafeId,
            pwb::catalog::place_managed_file(
                incoming / "dup.bin", scratch.project,
                pwb::domain::DataStage::Raw, ".hidden", "ver_x"));
        check_error_case(
            "err_unsafe_version", pwb::domain::ErrorCode::UnsafeId,
            pwb::catalog::place_managed_file(
                incoming / "dup.bin", scratch.project,
                pwb::domain::DataStage::Raw, "asset_px", "a/b"));
        PWB_CHECK(!fs::exists(scratch.root / "demo.artifacts" / "raw" / "../evil"));
    }
    // repr() quote-switch: an id containing a single quote renders with
    // double quotes, exactly like Python's !r.
    {
        check_error_case(
            "err_unsafe_asset_quote", pwb::domain::ErrorCode::UnsafeId,
            pwb::catalog::place_managed_file(
                incoming / "dup.bin", scratch.project,
                pwb::domain::DataStage::Raw, "ev'il", "ver_x"));
    }
    // Unicode alnum ids are safe in Python (str.isalnum) and reach
    // placement; the C++ gate accepts them (declared superset, D14).
    {
        auto result = pwb::catalog::place_managed_file(
            incoming / "one.bin", scratch.project, pwb::domain::DataStage::Raw,
            "asset_资产1", "ver_utf8");
        PWB_CHECK(result.is_ok());
        if (result.is_ok()) {
            PWB_CHECK(result.value().rel_path
                      == oracle["cases"]["ok_unicode_asset_id"]["rel_path"]
                             .get<std::string>());
        }
        // Traversal stays rejected regardless of the Unicode superset.
        auto traversal = pwb::catalog::place_managed_file(
            incoming / "dup.bin", scratch.project,
            pwb::domain::DataStage::Raw, "资产/../evil", "ver_x");
        PWB_CHECK(!traversal.is_ok());
    }
}

PWB_TEST(entity_page_rows_match_python_for_every_query) {
    Scratch scratch = Scratch::from_scenario("paged_queries");
    const CatalogDocument document = load_document(scratch);
    const Json oracle = load_json(scenario_dir("paged_queries") / "oracle.json");

    for (const auto& entry : oracle["queries"]) {
        const pwb::catalog::EntityPageQuery query =
            query_from_json(entry["query"]);
        const std::vector<Json> rows =
            pwb::catalog::search_assets_page(document, query);
        const Json& expected = entry["rows"];
        if (rows.size() != expected.size()) {
            std::cout << "  FAIL [" << entry["name"].get<std::string>()
                      << "] page size " << rows.size() << " != "
                      << expected.size() << "\n";
            PWB_CHECK(false);
            continue;
        }
        for (std::size_t i = 0; i < rows.size(); ++i) {
            check_row_matches(expected[i], rows[i]);
        }
        const std::int64_t count = pwb::catalog::count_assets(document, query);
        if (count != entry["count"].get<std::int64_t>()) {
            std::cout << "  FAIL [" << entry["name"].get<std::string>()
                      << "] count " << count << " != "
                      << entry["count"].get<std::int64_t>() << "\n";
            PWB_CHECK(false);
            continue;
        }
        PWB_CHECK(true);
    }
}

PWB_TEST(entity_page_orderings_and_keyset_are_stable) {
    Scratch scratch = Scratch::from_scenario("paged_queries", "order");
    const CatalogDocument document = load_document(scratch);

    // Two consecutive pages via offset equal one page via the keyset cursor:
    // the pagination is stable under deep paging.
    pwb::catalog::EntityPageQuery first;
    first.limit = 5;
    auto page0 = pwb::catalog::search_assets_page(document, first);
    PWB_CHECK(page0.size() == 5);
    first.offset = 5;
    auto page1 = pwb::catalog::search_assets_page(document, first);
    PWB_CHECK(page1.size() >= 1);

    pwb::catalog::EntityPageQuery keyset;
    keyset.limit = 5;
    keyset.after = {page0.back()["name"].get<std::string>(),
                    page0.back()["id"].get<std::string>()};
    auto keyed = pwb::catalog::search_assets_page(document, keyset);
    PWB_CHECK(keyed.size() == page1.size());
    const std::size_t shared =
        std::min(keyed.size(), page1.size());
    for (std::size_t i = 0; i < shared; ++i) {
        PWB_CHECK(keyed[i]["id"] == page1[i]["id"]);
    }

    // NULL current-version rows sort first on the version-column orders
    // (SQLite ASC NULLs-first contract), id tail keeps every order stable.
    pwb::catalog::EntityPageQuery by_size;
    by_size.order_by = "size";
    auto sized = pwb::catalog::search_assets_page(document, by_size);
    PWB_CHECK(!sized.empty());
    auto nulls_first = [](const Json& row) {
        return row["current_size_bytes"].is_null();
    };
    std::size_t i = 0;
    while (i < sized.size() && nulls_first(sized[i])) ++i;
    for (std::size_t j = i; j < sized.size(); ++j) {
        PWB_CHECK(!nulls_first(sized[j]));
    }

    // Unknown order falls back to name.
    pwb::catalog::EntityPageQuery bogus;
    bogus.order_by = "bogus";
    auto ordered = pwb::catalog::search_assets_page(document, bogus);
    bool sorted_by_name = std::is_sorted(
        ordered.begin(), ordered.end(),
        [](const Json& a, const Json& b) {
            return std::pair<std::string, std::string>{
                       a["name"].get<std::string>(), a["id"].get<std::string>()}
                < std::pair<std::string, std::string>{
                       b["name"].get<std::string>(), b["id"].get<std::string>()};
        });
    PWB_CHECK(sorted_by_name);
}

PWB_TEST(normalize_search_name_is_the_bounded_fold) {
    // ASCII case folds; CJK passes through verbatim (the declared bounded
    // parity envelope, matching the write side).
    PWB_CHECK(pwb::catalog::normalize_search_name("Well_008-Gulf 相带")
              == "well_008-gulf 相带");
    // Whitespace is PRESERVED for the search fold (db.py
    // normalize_asset_search_name is NFKC+casefold only).
    PWB_CHECK(pwb::catalog::normalize_search_name("  A   B  ")
              == "  a   b  ");
    // The collapse lives only in the tag normalizer (models.py
    // normalize_tag_name).
    PWB_CHECK(pwb::catalog::normalize_tag_name("  A   B  ") == "a b");
    PWB_CHECK(pwb::catalog::normalize_tag_name("QC_OK") == "qc_ok");
}
